const {execFileSync,execFile}=require('child_process');
const fs=require('fs');
const EXE='/workspace/dataset/test13_executable';
function run(a,b){
  const r=require('child_process').spawnSync(EXE,['--a',a,'--b',b],{encoding:'utf8'});
  const o={a,b,out:r.stdout,exit:r.status};
  if(r.stderr) o.stderr=r.stderr;
  return o;
}
function runArgv(argv){
  const r=require('child_process').spawnSync(EXE,argv,{encoding:'utf8'});
  const o={a:null,b:null,out:r.stdout,exit:r.status,argv};
  if(r.stderr) o.stderr=r.stderr;
  return o;
}
